func (j orderPartJoins[Q]) aliasedAs(alias string) orderPartJoins[Q] {
	return buildOrderPartJoins[Q](buildOrderPartColumns(alias), j.typ)
}

func buildOrderPartJoins[Q dialect.Joinable](cols orderPartColumns, typ string) orderPartJoins[Q] {
	return orderPartJoins[Q]{
		typ: typ,
		Order: modAs[Q, orderColumns]{
			c: Orders.Columns,
			f: func(to orderColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Orders.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.OrderID),
					))
				}

				return mods
			},
		},
	}
}
